begin;
create table if not exists public.sanji_brand_auto_config(owner uuid primary key references auth.users(id) on delete cascade, enabled boolean not null default false, enabled_at timestamptz, updated timestamptz not null default now());
create table if not exists public.sanji_brand_auto_runs(owner uuid not null references auth.users(id) on delete cascade, lead_id uuid not null references public.sanji_discovery_leads(id) on delete cascade, company_key text not null, candidate_id uuid not null, draft_id uuid not null, job_id uuid not null, created timestamptz not null default now(), primary key(owner,lead_id),unique(owner,company_key));
create table if not exists public.sanji_brand_auto_failures(owner uuid not null references auth.users(id) on delete cascade,lead_id uuid not null references public.sanji_discovery_leads(id) on delete cascade,attempts integer not null default 0,next_attempt timestamptz,updated timestamptz not null default now(),primary key(owner,lead_id));
alter table public.sanji_brand_auto_failures enable row level security;
revoke all on public.sanji_brand_auto_failures from public,anon,authenticated;
grant all on public.sanji_brand_auto_failures to service_role;
alter table public.sanji_brand_auto_config enable row level security;
alter table public.sanji_brand_auto_runs enable row level security;
revoke all on public.sanji_brand_auto_config,public.sanji_brand_auto_runs from public,anon,authenticated;
grant all on public.sanji_brand_auto_config,public.sanji_brand_auto_runs to service_role;
create or replace function public.sanji_brand_auto_commit(p_owner uuid,p_lead uuid,p_lead_updated timestamptz,p_candidate uuid,p_company_key text,p_candidate_data jsonb,p_draft_data jsonb,p_hash text,p_run_at timestamptz) returns jsonb language plpgsql security definer set search_path='' as $$
declare l public.sanji_discovery_leads;c public.sanji_brand_auto_config;t public.sanji_records;d uuid;j public.sanji_jobs;prior public.sanji_brand_auto_runs;
begin
 if not exists(select 1 from public.sanji_members where user_id=p_owner) then raise exception '권한 없음';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_owner::text,0));
 select * into prior from public.sanji_brand_auto_runs where owner=p_owner and lead_id=p_lead;
 if found then return jsonb_build_object('status','already_scheduled','jobId',prior.job_id);end if;
 select * into c from public.sanji_brand_auto_config where owner=p_owner for update;
 select * into l from public.sanji_discovery_leads where owner=p_owner and id=p_lead for update;
 if not found or not coalesce(c.enabled,false) or c.enabled_at is null or l.status<>'review' or l.updated<>p_lead_updated or coalesce(l.data->>'firstEmailAt','')='' or (l.data->>'firstEmailAt')::timestamptz<c.enabled_at then raise exception '활성화 이후 신규 발굴·최신 검증 대상이 아닙니다.';end if;
 if coalesce(p_company_key,'')='' or p_candidate_data->>'companyKey'<>p_company_key or p_candidate_data->>'kind'<>'브랜드' or p_draft_data->>'target'<>p_candidate::text or p_draft_data->>'channel'<>'email' or p_draft_data->>'replyTo' is not null or jsonb_array_length(coalesce(p_draft_data->'emails','[]'::jsonb))<>1 or lower(p_draft_data->>'email')<>lower(p_candidate_data#>>'{contact,email}') or lower(p_draft_data->'emails'->>0)<>lower(p_candidate_data#>>'{contact,email}') then raise exception '자동 예약 대상 검증 실패';end if;
 if p_run_at<=now() or extract(hour from p_run_at at time zone 'Asia/Seoul')<>9 or extract(minute from p_run_at at time zone 'Asia/Seoul')<>0 or extract(isodow from p_run_at at time zone 'Asia/Seoul') not between 1 and 5 then raise exception '안전한 평일 오전 9시 예약이 아닙니다.';end if;
 if exists(select 1 from public.sanji_brand_auto_runs where owner=p_owner and company_key=p_company_key) or exists(select 1 from public.sanji_records where owner=p_owner and kind='candidate' and (lower(data->>'companyKey')=lower(p_company_key) or lower(data#>>'{contact,email}')=lower(p_candidate_data#>>'{contact,email}') or exists(select 1 from jsonb_array_elements_text(coalesce(data->'recipientEmails','[]'::jsonb)) e where lower(e)=lower(p_candidate_data#>>'{contact,email}')))) then raise exception '기존 회사 또는 연락처가 있습니다.';end if;
 select * into t from public.sanji_records where owner=p_owner and kind='template' and id=(p_draft_data->>'templateId')::uuid for share;
 if not found or t.version<>(p_draft_data->>'templateVersion')::integer then raise exception '템플릿이 변경됐습니다.';end if;
 if exists(select 1 from public.sanji_suppression where owner=p_owner and identity in (lower(p_candidate_data#>>'{contact,email}'),'email:'||lower(p_candidate_data#>>'{contact,email}'),'company:'||lower(p_company_key))) then raise exception '수신 거부 대상입니다.';end if;
 insert into public.sanji_records(id,owner,kind,data) values(p_candidate,p_owner,'candidate',p_candidate_data);
 update public.sanji_discovery_leads set status='imported',data=data||jsonb_build_object('candidateId',p_candidate,'outreach',coalesce(p_draft_data->'autoOutreach',data->'outreach','{}'::jsonb)),updated=now() where id=p_lead and owner=p_owner;
 insert into public.sanji_drafts(owner,data,hash,expires) values(p_owner,p_draft_data,p_hash,now()+interval '15 minutes') returning id into d;
 select * into j from public.sanji_schedule_dispatch(p_owner,d,p_hash,p_run_at);
 insert into public.sanji_brand_auto_runs(owner,lead_id,company_key,candidate_id,draft_id,job_id) values(p_owner,p_lead,p_company_key,p_candidate,d,j.id);
 insert into public.sanji_audit(owner,action,data) values(p_owner,'brand_auto_scheduled',jsonb_build_object('lead',p_lead,'job',j.id,'runAt',p_run_at,'approval','standing_brand_auto'));
 return jsonb_build_object('status','scheduled','jobId',j.id,'runAt',p_run_at);
end $$;
revoke all on function public.sanji_brand_auto_commit(uuid,uuid,timestamptz,uuid,text,jsonb,jsonb,text,timestamptz) from public,anon,authenticated;
grant execute on function public.sanji_brand_auto_commit(uuid,uuid,timestamptz,uuid,text,jsonb,jsonb,text,timestamptz) to service_role;
commit;
